<?php namespace App\Http\Controllers\Inventory;
use App\Http\Controllers\Controller; use App\Models\{Category,Brand,Unit,Warehouse}; use App\Services\AuditLogger; use Illuminate\Http\Request;
class SetupController extends Controller {
 public function categories(){return view('inventory.categories.index',['items'=>Category::latest()->paginate(15)]);} public function storeCategory(Request $r,AuditLogger $a){$d=$r->validate(['name'=>'required|string|max:100|unique:categories,name','description'=>'nullable|string|max:500']);$x=Category::create($d);$a->record($r,'inventory.category_created','success',['id'=>$x->id]);return back()->with('success','Category added.');}
 public function brands(){return view('inventory.brands.index',['items'=>Brand::latest()->paginate(15)]);} public function storeBrand(Request $r,AuditLogger $a){$d=$r->validate(['name'=>'required|string|max:100|unique:brands,name']);$x=Brand::create($d);$a->record($r,'inventory.brand_created','success',['id'=>$x->id]);return back()->with('success','Brand added.');}
 public function units(){return view('inventory.units.index',['items'=>Unit::latest()->paginate(15)]);} public function storeUnit(Request $r,AuditLogger $a){$d=$r->validate(['name'=>'required|string|max:80|unique:units,name','short_name'=>'required|string|max:20|unique:units,short_name','conversion_rate'=>'required|numeric|min:.0001|max:999999']);$x=Unit::create($d);$a->record($r,'inventory.unit_created','success',['id'=>$x->id]);return back()->with('success','Unit added.');}
 public function warehouses(){return view('inventory.warehouses.index',['items'=>Warehouse::latest()->paginate(15)]);} public function storeWarehouse(Request $r,AuditLogger $a){$d=$r->validate(['name'=>'required|string|max:120','code'=>'required|string|max:30|alpha_dash|unique:warehouses,code','location'=>'nullable|string|max:255']);$x=Warehouse::create($d);$a->record($r,'inventory.warehouse_created','success',['id'=>$x->id]);return back()->with('success','Warehouse added.');}
}
